/* 经纬度 -> viewBox 坐标（与上面的路径同一套投影） */
CHINA_MAP.project = function (lng, lat) {
  var y = Math.log(Math.tan(Math.PI / 4 + lat * Math.PI / 360)) * 180 / Math.PI;
  return [
    (lng - this.x0) * this.scale + this.pad,
    (-y - this.y0) * this.scale + this.pad
  ];
};
